#include <bits/stdc++.h>
using namespace std;
int main(int argc, char**argv){int m=stoi(argv[1]); using U=uint64_t; vector<pair<int,int>> E;for(int i=0;i<m;i++)for(int j=i+1;j<m;j++)E.push_back({i,j});int ne=E.size();vector<U> faces;faces.reserve(7000000);auto st=chrono::steady_clock::now();for(auto [i,j]:E){vector<U> all(1,0);for(int k=0;k<ne;k++)if(E[k].first==i||E[k].second==i||E[k].first==j||E[k].second==j){size_t sz=all.size();for(size_t t=0;t<sz;t++) all.push_back(all[t]|(1ULL<<k));}faces.insert(faces.end(),all.begin()+1,all.end());}sort(faces.begin(),faces.end());faces.erase(unique(faces.begin(),faces.end()),faces.end());auto N=faces.size();cerr<<"faces "<<N<<"\n";unordered_map<U,int> index;index.reserve((size_t)(N*1.38)); index.max_load_factor(.85);for(size_t k=0;k<N;k++)index.emplace(faces[k],k);cerr<<"indexed\n";vector<int> lohi(N,-1),hilo(N,-1);vector<char> unmatched(N,1);for(int k=0;k<ne;k++){U b=1ULL<<k;for(size_t a=0;a<N;a++) if(unmatched[a]&&!(faces[a]&b)){auto it=index.find(faces[a]|b);if(it!=index.end()&&unmatched[it->second]){int h=it->second;unmatched[a]=unmatched[h]=0;lohi[a]=h;hilo[h]=a;}}}map<int,int>crit;int count=0;for(size_t a=0;a<N;a++)if(unmatched[a]){crit[__builtin_popcountll(faces[a])-1]++;count++;}cerr<<"critical "<<count<<" ";for(auto [k,v]:crit)cerr<<k<<":"<<v<<",";cerr<<"\n";vector<int> indeg(N,0);long long cov=0;for(int h=0;h<(int)N;h++){U x=faces[h];while(x){U b=x&(-x);x-=b;U y=faces[h]^b;if(!y)continue;auto it=index.find(y);if(it==index.end()){cerr<<"NOT DOWNWARD CLOSED\n";return 5;}int l=it->second;if(lohi[l]==h)indeg[h]++;else indeg[l]++;cov++;}}cerr<<"covers "<<cov<<"\n";deque<int> q;for(int i=0;i<(int)N;i++)if(indeg[i]==0)q.push_back(i);long long proc=0;while(!q.empty()){int h=q.front();q.pop_front();proc++;U x=faces[h];while(x){U b=x&(-x);x-=b;U y=faces[h]^b;if(!y)continue;auto it=index.find(y);int l=it->second;if(hilo[h]==l)continue;if(--indeg[l]==0)q.push_back(l);}int hi=lohi[h];if(hi>=0&&--indeg[hi]==0)q.push_back(hi);}cerr<<"ACYC "<<(proc==(long long)N)<<" processed "<<proc<<" of "<<N<<"\n";return proc==(long long)N?0:1;}
